import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"怀沙","description":"","frontmatter":{"title":"怀沙","date":"2026-11-24T00:00:00.000Z","seq":18,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"抽思","link":"/blogs/楚辞/抽思.html"},"next":{"text":"思美人","link":"/blogs/楚辞/思美人.html"}},"headers":[],"relativePath":"blogs/楚辞/怀沙.md","filePath":"blogs/楚辞/怀沙.md"}'),o={name:"blogs/楚辞/怀沙.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="怀沙" tabindex="-1">怀沙 <a class="header-anchor" href="#怀沙" aria-label="Permalink to &quot;怀沙&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">滔滔孟夏兮，草木莽莽。</p><p class="poem-stanza">伤怀永哀兮，汩徂南土。</p><p class="poem-stanza">眴兮杳杳，孔静幽默。</p><p class="poem-stanza">郁结纡轸兮，离慜而长鞠。</p><p class="poem-stanza">抚情效志兮，冤屈而自抑。</p><p class="poem-stanza">刓方以为圜兮，常度未替。</p><p class="poem-stanza">易初本迪兮，君子所鄙。</p><p class="poem-stanza">章画志墨兮，前图未改。</p><p class="poem-stanza">内厚质正兮，大人所盛。</p><p class="poem-stanza">巧倕不斲兮，孰察其拨正。</p><p class="poem-stanza">玄文处幽兮，矇瞍谓之不章</p><p class="poem-stanza">离娄微睇兮，瞽以为无明。</p><p class="poem-stanza">变白以为黑兮，倒上以为下。</p><p class="poem-stanza">凤皇在笯兮，鸡鹜翔舞。</p><p class="poem-stanza">同糅玉石兮，一概而相量。</p><p class="poem-stanza">夫惟党人之鄙固兮，羌不知余之所臧。</p><p class="poem-stanza">任重载盛兮，陷滞而不济。</p><p class="poem-stanza">怀瑾握瑜兮，穷不知所示。</p><p class="poem-stanza">邑犬之群吠兮，吠所怪也。</p><p class="poem-stanza">非俊疑杰兮，固庸态也。</p><p class="poem-stanza">文质疏内兮，众不知余之异采。</p><p class="poem-stanza">材朴委积兮，莫知余之所有。</p><p class="poem-stanza">重仁袭义兮，谨厚以为丰。</p><p class="poem-stanza">重华不可遌兮，孰知余之从容！</p><p class="poem-stanza">古固有不并兮，岂知其何故也？</p><p class="poem-stanza">汤禹久远兮，邈而不可慕也？</p><p class="poem-stanza">惩违改忿兮，抑心而自强。</p><p class="poem-stanza">离慜而不迁兮，愿志之有像。</p><p class="poem-stanza">进路北次兮，日昧昧其将暮。</p><p class="poem-stanza">舒忧娱哀兮，限之以大故。</p><p class="poem-stanza">乱曰：</p><p class="poem-stanza">浩浩沅湘，分流汩兮。</p><p class="poem-stanza">修路幽蔽，道远忽兮。</p><p class="poem-stanza">怀质抱情，独无匹兮。</p><p class="poem-stanza">伯乐既没，骥焉程兮。</p><p class="poem-stanza">民生禀命，各有所错兮。</p><p class="poem-stanza">定心广志，余何所畏惧兮？</p><p class="poem-stanza">曾伤爰哀，永叹喟兮。</p><p class="poem-stanza">世浑浊莫吾知，人心不可谓兮。</p><p class="poem-stanza">知死不可让，愿勿爱兮。</p><p class="poem-stanza">明告君子，吾将以为类兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
